create table public.atlas_original_places (
 position smallint not null unique,
 id text primary key,
 document jsonb not null
);
alter table public.atlas_original_places enable row level security;
revoke all on public.atlas_original_places from public, anon, authenticated;
grant select on public.atlas_original_places to anon, authenticated;
create policy "Read original exhibitions" on public.atlas_original_places for select to anon, authenticated using (true);
insert into public.atlas_original_places(position,id,document) values
(1,'paleocristiano',$place${"id":"paleocristiano","label":"Paleocristiano","culture":"ARQUITECTURA PALEOCRISTIANA","name":"San Pedro","country":"VATICANO","period":"Siglo IV","lat":41.9022,"lon":12.4539,"coords":"41.9022° N / 12.4539° E","headline":"La basílica como lugar de encuentro.","text":"La antigua basílica de San Pedro, impulsada por Constantino en el siglo IV, es un referente de la arquitectura paleocristiana. Su organización longitudinal, con cinco naves, atrio y ábside, orientaba a la comunidad hacia el altar y la memoria del apóstol.","detail":"El edificio original no se conserva en pie. Fue sustituido por la basílica actual, cuya construcción comenzó en 1506 y concluyó en 1626. La comparación muestra dos edificios distintos en el mismo lugar.","fact":"Planta basilical y cinco naves","main":"paleo-historico","second":"paleo-actual","caption":"Antigua San Pedro · reconstrucción gráfica de H. W. Brewer, 1891. Representa su aspecto tardomedieval, con modificaciones posteriores al siglo IV.","caption2":"Basílica actual de San Pedro · fotografía de 2019. Sustituyó al edificio paleocristiano; no es su estado original restaurado.","status":"EDIFICIO ORIGINAL REEMPLAZADO","source":"https://www.basilicasanpietro.va/en/faq/when-was-st-peters-basilica-built","sourceName":"Basílica de San Pedro","history":true,"credits":[{"id":"paleo-historico","path":"assets/paleo-historico.jpg","source":"https://commons.wikimedia.org/wiki/File:Basilica_di_San_Pietro_1450.jpg","image_url":"https://upload.wikimedia.org/wikipedia/commons/d/df/Basilica_di_San_Pietro_1450.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled","credit":"H.W. Brewer (1836 – 1903)[1]","license":"Public domain","license_url":"https://commons.wikimedia.org/wiki/File:Basilica_di_San_Pietro_1450.jpg","description":"Drawing and graphic reconstruction of the Constantinian basilica over the grave of St. Peter in Rome. The figure shows, according to the caption, the building in 1450. In the right background, however, the Sistine Chapel can be seen, whose construction started in 1475 and finished in 1483. Since the foundation stone was laid for the new St. Peter's Cathedral in 1506, the drawing shows the state between 1483 and 1506. Drawing from H.W.Brewer, 1891","date":"1891date QS:P571,+1891-00-00T00:00:00Z/9","changes":"Redimensionada para web; mostrada sin recorte en la comparación."},{"id":"paleo-actual","path":"assets/paleo-actual.jpg","source":"https://commons.wikimedia.org/wiki/File:St._Peter%27s_Basilica_and_its_dome.jpg","image_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3c/St._Peter%27s_Basilica_and_its_dome.jpg/1280px-St._Peter%27s_Basilica_and_its_dome.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","credit":"Vitold Muratov","license":"CC BY-SA 4.0","license_url":"https://creativecommons.org/licenses/by-sa/4.0","description":"St. Peter's Cathedral with a height of 120 m, and its dome","date":"2019-02-22","changes":"Redimensionada para web; mostrada sin recorte en la comparación."}],"detailDocument":null}$place$::jsonb),
(2,'bizantino',$place${"id":"bizantino","label":"Bizantino","culture":"IMPERIO BIZANTINO","name":"Santa Sofía","country":"TURQUÍA","period":"532–537 d. C.","lat":41.0086,"lon":28.9802,"coords":"41.0086° N / 28.9802° E","headline":"Una cúpula que transforma el espacio.","text":"Construida en Constantinopla bajo Justiniano, Santa Sofía es una obra emblemática del mundo bizantino. Antemio de Trales e Isidoro de Mileto combinaron una gran cúpula sobre pechinas con semicúpulas y un interior monumental atravesado por la luz.","detail":"El edificio se conserva en Estambul, con reparaciones y añadidos de distintas épocas. Los minaretes pertenecen a su transformación otomana. La ilustración histórica es de 1857: documenta esa etapa posterior y no reconstruye el templo del siglo VI.","fact":"Cúpula sobre pechinas","main":"bizantino-historico","second":"bizantino-actual","caption":"Santa Sofía · ilustración de 1857, ya en época otomana. No representa su aspecto bizantino original.","caption2":"Santa Sofía en Estambul · fotografía de enero de 2023. Se conservan la estructura histórica y añadidos de épocas posteriores.","status":"EDIFICIO CONSERVADO Y TRANSFORMADO","source":"https://whc.unesco.org/en/list/356/","sourceName":"UNESCO","history":true,"credits":[{"id":"bizantino-historico","path":"assets/bizantino-historico.jpg","source":"https://commons.wikimedia.org/wiki/File:Sainte-sophie,_a_Constantinople.jpg","image_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/07/Sainte-sophie%2C_a_Constantinople.jpg/1280px-Sainte-sophie%2C_a_Constantinople.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","credit":"Autor desconocido; digitalización de Dmitry Makeev","license":"Public domain","license_url":"https://commons.wikimedia.org/wiki/File:Sainte-sophie,_a_Constantinople.jpg","description":"Hagia Sophia (The Church of the Holy Wisdom), Constantinople – The Most Beautiful Churches of the World","date":"1857date QS:P571,+1857-00-00T00:00:00Z/9","changes":"Redimensionada para web; mostrada sin recorte en la comparación."},{"id":"bizantino-actual","path":"assets/bizantino-actual.jpg","source":"https://commons.wikimedia.org/wiki/File:Ayasofya_Camii_(20230126).jpg","image_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e0/Ayasofya_Camii_%2820230126%29.jpg/1280px-Ayasofya_Camii_%2820230126%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","credit":"Kadı","license":"CC BY 2.0","license_url":"https://creativecommons.org/licenses/by/2.0","description":"Hagia Sophia Mosque","date":"2023-01-26 20:44:08","changes":"Redimensionada para web; mostrada sin recorte en la comparación."}],"detailDocument":{"schemaVersion":1,"title":"Santa Sofía · Referencia de aceptación","blocks":[{"id":"portada","type":"hero","title":"Dentro de\nSanta Sofía.","layout":"reading","eyebrow":"ESTAMBUL / ESPACIO E HISTORIA","description":"Tres maneras de leer el espacio.\nQuince momentos para entender su historia."},{"id":"analisis","type":"section","title":"La masa y el vacío.","layout":"reading","description":"Una misma geometría, tres lecturas. Abre cada lámina para observarla en detalle.","children":[{"id":"laminas","type":"plates","title":"","layout":"three-columns","items":[{"src":"/assets/sophia-vacios.svg?v=2","alt":"Mapa de vacíos de Santa Sofía","caption":"El negro destaca los espacios interiores: nártex, naves laterales, nave central y ábside. Permite leer sus conexiones y proporciones generales.","label":"01 / VACÍOS","title":"El espacio habitable"},{"src":"/assets/sophia-llenos.svg?v=2","alt":"Mapa de llenos de Santa Sofía","caption":"El negro identifica la masa de muros, pilares y columnas. El blanco deja ver el espacio libre entre los elementos que delimitan y sostienen el edificio.","label":"02 / LLENOS","title":"La materia que sostiene"},{"src":"/assets/sophia-nolli.svg?v=2","alt":"Mapa de Nolli de Santa Sofía","caption":"El blanco vincula el espacio exterior de llegada con el interior colectivo, atravesando el nártex. Es una interpretación del principio Nolli aplicada al edificio.","label":"03 / NOLLI","title":"El interior como continuidad"}]}]},{"id":"historia","type":"timeline","title":"Un edificio.\nMuchas vidas.","layout":"reading","description":"Incendios, imperios, reconstrucciones y nuevas formas de habitar lo sagrado. Sigue los momentos que transformaron Santa Sofía y la ciudad a su alrededor.","range":"360 — 2020","events":[{"date":"360","era":"Antes del edificio actual","tags":["Arquitectura","Sociedad"],"title":"La primera iglesia","body":"Bajo Constancio II se dedica la primera iglesia en este lugar. Es el comienzo de su historia, pero todavía no es el edificio que vemos hoy.","source":{"name":"The Metropolitan Museum of Art","url":"https://www.metmuseum.org/essays/hagia-sophia-532-37"}},{"date":"404","era":"Las iglesias anteriores","tags":["Sociedad"],"title":"Un incendio interrumpe su historia","body":"La primera iglesia queda destruida durante disturbios. El destino del templo ya está ligado a los conflictos de Constantinopla.","source":{"name":"The Metropolitan Museum of Art","url":"https://www.metmuseum.org/essays/hagia-sophia-532-37"}},{"date":"415","era":"Las iglesias anteriores","tags":["Arquitectura","Política"],"title":"Una segunda Santa Sofía","body":"Teodosio II inaugura una nueva iglesia. También desaparecerá: el monumento actual es la tercera gran construcción del lugar.","source":{"name":"The Metropolitan Museum of Art","url":"https://www.metmuseum.org/essays/hagia-sophia-532-37"}},{"date":"532","era":"Constantinopla bizantina","tags":["Política","Sociedad"],"title":"La revuelta de Niká","body":"La segunda iglesia arde durante la rebelión contra Justiniano. El emperador ordena reconstruirla: una crisis urbana da paso a una obra monumental.","source":{"name":"The Metropolitan Museum of Art","url":"https://www.metmuseum.org/essays/hagia-sophia-532-37"}},{"date":"532–537","era":"Constantinopla bizantina","tags":["Economía","Arquitectura"],"title":"Los recursos de un imperio","body":"La construcción reúne materiales de distintas regiones del imperio. Los mármoles y las columnas hacen visible su riqueza; entender esta obra también implica pensar en el transporte, los oficios y los recursos que la hicieron posible.","source":{"name":"The Metropolitan Museum of Art","url":"https://www.metmuseum.org/exhibitions/listings/2012/byzantium-and-islam/blog/where-in-the-world/posts/hagia-sophia"}},{"date":"537","era":"Constantinopla bizantina","tags":["Arquitectura"],"title":"Se inaugura el edificio actual","body":"El 27 de diciembre se dedica la obra de Antemio de Trales e Isidoro de Mileto. Su gran cúpula redefine el espacio interior.","source":{"name":"The Metropolitan Museum of Art","url":"https://www.metmuseum.org/essays/hagia-sophia-532-37"}},{"date":"558–562","era":"Constantinopla bizantina","tags":["Arquitectura"],"title":"La cúpula se reconstruye","body":"La primera cúpula colapsa en 558. Se reconstruye con un perfil más elevado y la iglesia vuelve a dedicarse en 562.","source":{"name":"The Metropolitan Museum of Art","url":"https://www.metmuseum.org/essays/hagia-sophia-532-37"}},{"date":"843","era":"Constantinopla bizantina","tags":["Arte","Sociedad"],"title":"El regreso de las imágenes","body":"Termina la iconoclasia bizantina. Después se incorporan mosaicos figurativos: el interior cambia junto con la relación religiosa con las imágenes.","source":{"name":"The Metropolitan Museum of Art","url":"https://www.metmuseum.org/essays/hagia-sophia-532-37"}},{"date":"1204","era":"Una capital disputada","tags":["Política"],"title":"La Cuarta Cruzada","body":"Los cruzados toman Constantinopla y comienza el dominio latino. Este cambio de poder rompe la continuidad política bizantina de la ciudad que alberga Santa Sofía.","source":{"name":"The Metropolitan Museum of Art","url":"https://www.metmuseum.org/exhibitions/listings/2004/byzantium-faith-and-power"}},{"date":"1261","era":"Una capital disputada","tags":["Política"],"title":"El regreso bizantino","body":"Los bizantinos recuperan Constantinopla tras 57 años de dominio latino. La ciudad vuelve a ser capital imperial, en una nueva etapa de su historia religiosa y artística.","source":{"name":"The Metropolitan Museum of Art","url":"https://www.metmuseum.org/exhibitions/listings/2004/byzantium-faith-and-power"}},{"date":"1453","era":"Estambul otomana","tags":["Política","Arquitectura"],"title":"De iglesia a mezquita","body":"Tras la conquista otomana, Mehmed II convierte Santa Sofía en mezquita. En esta nueva etapa se añaden elementos para el culto islámico; los minaretes y otras intervenciones transforman progresivamente el conjunto.","source":{"name":"Dijital Istanbul","url":"https://dijitalistanbul.org/en/hagia-sophia-grand-mosque"}},{"date":"1847–1849","era":"Estambul otomana","tags":["Arquitectura","Patrimonio"],"title":"Restaurar y documentar","body":"Los hermanos Gaspare y Giuseppe Fossati restauran el monumento. Sus representaciones documentan una etapa de su vida otomana y permiten estudiar cómo se veía en el siglo XIX.","source":{"name":"Museo de Cultura Bizantina","url":"https://www.mbp.gr/en/exhibition/i-agia-sofia-ton-adelfon-fossati-mesa-apo-ti-2/"}},{"date":"1935","era":"La República de Turquía","tags":["Sociedad","Patrimonio"],"title":"Santa Sofía abre como museo","body":"Su apertura como museo introduce una nueva forma de recorrer el edificio: además de su historia religiosa, cobra protagonismo su lectura como monumento histórico y artístico.","source":{"name":"Dijital Istanbul","url":"https://dijitalistanbul.org/en/hagia-sophia-grand-mosque"}},{"date":"1985","era":"Un patrimonio compartido","tags":["Patrimonio"],"title":"Reconocimiento mundial","body":"Las Zonas Históricas de Estambul ingresan en la Lista del Patrimonio Mundial de la UNESCO. Santa Sofía forma parte de este conjunto, reconocido por el encuentro de la arquitectura bizantina y otomana.","source":{"name":"UNESCO","url":"https://whc.unesco.org/en/list/356/"}},{"date":"2020","era":"Un patrimonio compartido","tags":["Política","Sociedad","Patrimonio"],"title":"Un nuevo cambio de uso","body":"El 10 de julio se decide su reconversión en mezquita. La UNESCO subraya la necesidad de proteger su valor universal y de mantener el acceso a este patrimonio compartido.","source":{"name":"UNESCO","url":"https://www.unesco.org/en/articles/unesco-statement-hagia-sophia-istanbul"}}]}]}}$place$::jsonb),
(3,'carolingio',$place${"id":"carolingio","label":"Carolingio","culture":"IMPERIO CAROLINGIO","name":"Aquisgrán","country":"ALEMANIA","period":"Finales del siglo VIII–inicios del IX","lat":50.7747,"lon":6.0839,"coords":"50.7747° N / 6.0839° E","headline":"Una capilla para el poder imperial.","text":"La Capilla Palatina de Carlomagno es el núcleo de la catedral de Aquisgrán. Su espacio central octogonal, rodeado por un deambulatorio y tribunas, retoma modelos de la Antigüedad y del mundo bizantino para expresar el proyecto imperial carolingio.","detail":"El núcleo carolingio se conserva, integrado en una catedral ampliada durante siglos. La lámina histórica permite comparar plantas y secciones del conjunto; la fotografía muestra su exterior con transformaciones posteriores, que no deben atribuirse todas a Carlomagno.","fact":"Octógono central y tribunas","main":"carolingio-historico","second":"carolingio-actual","caption":"Catedral de Aquisgrán · plantas y secciones de Georg Dehio y Gustav von Bezold (1887–1901). Incluye el núcleo carolingio y ampliaciones posteriores.","caption2":"Capilla Palatina integrada en la catedral de Aquisgrán · fotografía de 2009. El núcleo octogonal sobrevive con añadidos posteriores.","status":"NÚCLEO CAROLINGIO CONSERVADO","source":"https://whc.unesco.org/en/list/3/","sourceName":"UNESCO","history":true,"credits":[{"id":"carolingio-historico","path":"assets/carolingio-historico.jpg","source":"https://commons.wikimedia.org/wiki/File:Aachen_Dehio_1887.jpg","image_url":"https://upload.wikimedia.org/wikipedia/commons/a/a9/Aachen_Dehio_1887.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled","credit":"Georg Dehio/Gustav von Bezold","license":"Public domain","license_url":"https://commons.wikimedia.org/wiki/File:Aachen_Dehio_1887.jpg","description":"Palace chapel of Aachen","date":"1887–1901","changes":"Redimensionada para web; mostrada sin recorte en la comparación."},{"id":"carolingio-actual","path":"assets/carolingio-actual.jpg","source":"https://commons.wikimedia.org/wiki/File:Cath%C3%A9drale_d%27Aix-la-Chapelle_04.jpg","image_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/Cath%C3%A9drale_d%27Aix-la-Chapelle_04.jpg/1280px-Cath%C3%A9drale_d%27Aix-la-Chapelle_04.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","credit":"Alex Riechert","license":"CC BY-SA 3.0","license_url":"https://creativecommons.org/licenses/by-sa/3.0","description":"Cathédrale d'Aix-la-Chapelle\nAix-la-Chapelle (Aachen)\n\nAllemagne","date":"2009-12-22 15:35:18","changes":"Redimensionada para web; mostrada sin recorte en la comparación."}],"detailDocument":null}$place$::jsonb),
(4,'inca',$place${"id":"inca","culture":"IMPERIO INCA","name":"Machu Picchu","country":"PERÚ","period":"Siglo XV","lat":-13.1631,"lon":-72.545,"coords":"13.1631° S / 72.5450° O","headline":"La montaña como arquitectura.","text":"En lo alto de los Andes, Machu Picchu transforma una pendiente en un lugar para habitar. Terrazas, escaleras y recintos de piedra se adaptan al relieve: la ciudad parece continuar la montaña.","detail":"Su arquitectura une el trabajo de la piedra con el manejo del agua y el paisaje. Los espacios agrícolas y ceremoniales forman parte de un mismo conjunto.","fact":"Piedra y terrazas","main":"inca-machu-picchu","second":"inca-sacred-valley","caption":"Machu Picchu y la montaña Huayna Picchu","caption2":"El conjunto arqueológico y su paisaje andino","source":"https://whc.unesco.org/en/list/274/","sourceName":"UNESCO","credits":[{"id":"inca-machu-picchu","path":"assets/inca-machu-picchu.jpg","source":"https://commons.wikimedia.org/wiki/File:99_-_Machu_Picchu_-_Juin_2009.jpg","image_url":"https://upload.wikimedia.org/wikipedia/commons/a/a8/99_-_Machu_Picchu_-_Juin_2009.jpg","credit":"Martin St-Amant — Wikipedia","license":"CC BY-SA 3.0","license_url":"https://creativecommons.org/licenses/by-sa/3.0/","bytes":238209,"changes":"Resized for website; display may crop to fit"},{"id":"inca-sacred-valley","path":"assets/inca-sacred-valley.jpg","source":"https://commons.wikimedia.org/wiki/File:Panoramic_Image_of_Machu_Picchu_and_the_Sacred_Valley.jpg","image_url":"https://upload.wikimedia.org/wikipedia/commons/b/b0/Panoramic_Image_of_Machu_Picchu_and_the_Sacred_Valley.jpg","credit":"Rubyk; stitched/edited by Fir0002; cropped by Dschwen","license":"CC BY-SA 2.5","license_url":"https://creativecommons.org/licenses/by-sa/2.5/","bytes":370814,"changes":"Resized for website; display may crop to fit"}],"detailDocument":null}$place$::jsonb),
(5,'muisca',$place${"id":"muisca","culture":"CULTURA MUISCA","name":"Guatavita","country":"COLOMBIA","period":"Época prehispánica","lat":4.977,"lon":-73.775,"coords":"4.9770° N / 73.7750° O","headline":"Un territorio tejido de agua y memoria.","text":"Para los muiscas del altiplano cundiboyacense, las lagunas eran lugares sagrados. Guatavita conserva la memoria de las ofrendas y de una relación con el paisaje que iba más allá de lo material.","detail":"La balsa muisca representa una ceremonia de ofrenda asociada al relato de El Dorado. Fue hallada en Pasca, no en esta laguna, y hoy se conserva en el Museo del Oro de Bogotá.","fact":"Paisaje sagrado","main":"muisca-raft","second":"muisca-guatavita","caption":"Balsa muisca · Museo del Oro, Bogotá","caption2":"Laguna de Guatavita · Sesquilé, Cundinamarca","source":"https://enciclopedia.banrepcultural.org/Balsa_muisca","sourceName":"Banco de la República","credits":[{"id":"muisca-guatavita","path":"assets/muisca-guatavita.jpg","source":"https://commons.wikimedia.org/wiki/File:LagunaDeGuatavita.jpg","image_url":"https://upload.wikimedia.org/wikipedia/commons/6/64/LagunaDeGuatavita.jpg","credit":"Masanalv; cropped by Ras67","license":"CC BY 3.0","license_url":"https://creativecommons.org/licenses/by/3.0/","bytes":87441,"changes":"Resized for website; display may crop to fit"},{"id":"muisca-raft","path":"assets/muisca-raft.jpg","source":"https://commons.wikimedia.org/wiki/File:Gold_Museum%2C_Bogota_%2836145671394%29.jpg","image_url":"https://upload.wikimedia.org/wikipedia/commons/9/99/Gold_Museum%2C_Bogota_%2836145671394%29.jpg","credit":"Pedro Szekely","license":"CC BY-SA 2.0","license_url":"https://creativecommons.org/licenses/by-sa/2.0/","bytes":748193,"changes":"Resized for website; display may crop to fit"}],"detailDocument":null}$place$::jsonb),
(6,'roma',$place${"id":"roma","culture":"CIVILIZACIÓN ROMANA","name":"Roma","country":"ITALIA","period":"Antigüedad romana","lat":41.8902,"lon":12.4922,"coords":"41.8902° N / 12.4922° E","headline":"Construir la vida en común.","text":"En Roma, la arquitectura convirtió la ciudad en un escenario de vida pública. El Coliseo, los foros y los templos muestran distintas formas de reunir a una sociedad y expresar su poder.","detail":"El arco, la bóveda y la cúpula ampliaron las posibilidades del espacio. El Panteón conserva una de las expresiones más reconocibles de esa búsqueda: un gran interior organizado bajo una cúpula.","fact":"Arco, bóveda y cúpula","main":"rome-colosseum","second":"rome-pantheon","caption":"Coliseo · el anfiteatro de la ciudad antigua","caption2":"Panteón · el pórtico y la ciudad","source":"https://whc.unesco.org/en/list/91/","sourceName":"UNESCO","credits":[{"id":"rome-colosseum","path":"assets/rome-colosseum.jpg","source":"https://commons.wikimedia.org/wiki/File:Colosseum_exterior_%285200565537%29.jpg","image_url":"https://upload.wikimedia.org/wikipedia/commons/6/68/Colosseum_exterior_%285200565537%29.jpg","credit":"Weldon Kennedy","license":"CC BY 2.0","license_url":"https://creativecommons.org/licenses/by/2.0/","bytes":541362,"changes":"Resized for website; display may crop to fit"},{"id":"rome-pantheon","path":"assets/rome-pantheon.jpg","source":"https://commons.wikimedia.org/wiki/File:Pantheon_%28Roma%29_-_Front.jpg","image_url":"https://upload.wikimedia.org/wikipedia/commons/6/6d/Pantheon_%28Roma%29_-_Front.jpg","credit":"NikonZ7II","license":"CC BY-SA 4.0","license_url":"https://creativecommons.org/licenses/by-sa/4.0/","bytes":616556,"changes":"Resized for website; display may crop to fit"}],"detailDocument":null}$place$::jsonb),
(7,'egipto',$place${"id":"egipto","culture":"ANTIGUO EGIPTO","name":"Guiza","country":"EGIPTO","period":"III milenio a. C.","lat":29.9792,"lon":31.1342,"coords":"29.9792° N / 31.1342° E","headline":"La piedra frente al tiempo.","text":"En el borde del desierto, las pirámides de Guiza hacen visible la escala del poder faraónico. Forman parte de complejos funerarios donde la arquitectura articulaba la memoria del gobernante y las creencias sobre la vida después de la muerte.","detail":"Las pirámides, los templos y la Gran Esfinge pertenecen a un paisaje monumental. Su permanencia permite reconocer una manera de construir vinculada con el territorio y lo sagrado.","fact":"Conjunto funerario","main":"egypt-pyramids","second":"egypt-sphinx","caption":"Las pirámides de Guiza y el horizonte del desierto","caption2":"La Gran Esfinge y la pirámide de Keops","source":"https://whc.unesco.org/en/list/86/","sourceName":"UNESCO","credits":[{"id":"egypt-pyramids","path":"assets/egypt-pyramids.jpg","source":"https://commons.wikimedia.org/wiki/File:Panoramic_View_of_the_Pyramids_of_Giza.jpg","image_url":"https://upload.wikimedia.org/wikipedia/commons/1/19/Panoramic_View_of_the_Pyramids_of_Giza.jpg","credit":"Hosam Zidan","license":"CC BY-SA 4.0","license_url":"https://creativecommons.org/licenses/by-sa/4.0/","bytes":194402,"changes":"Resized for website; display may crop to fit"},{"id":"egypt-sphinx","path":"assets/egypt-sphinx.jpg","source":"https://commons.wikimedia.org/wiki/File:Sphinx_and_the_Great_Pyramid_of_Giza_panorama.jpg","image_url":"https://upload.wikimedia.org/wikipedia/commons/c/c0/Sphinx_and_the_Great_Pyramid_of_Giza_panorama.jpg","credit":"kallerna","license":"CC BY-SA 3.0","license_url":"https://creativecommons.org/licenses/by-sa/3.0/","bytes":179245,"changes":"Resized for website; display may crop to fit"}],"detailDocument":null}$place$::jsonb);
insert into storage.buckets(id,name,public) values ('atlas-originals','atlas-originals',true);
